/* oxlint-disable import/no-nodejs-modules -- build-time codegen script */
/*
 * Generates src/logger/reporting/reporter.gen.ts: the error-reporter mode
 * selected at build time, so the unselected reporter's module graph is
 * never referenced and Metro cannot include it.
 *
 *   node scripts/gen-error-reporter.js            # reads EXPO_PUBLIC_ERROR_REPORTER
 *   EXPO_PUBLIC_ERROR_REPORTER=bolide node scripts/gen-error-reporter.js
 *
 * Modes: bolide (default), none. The generated file is committed
 * to gitignore; it is an artifact.
 */
const fs = require('node:fs')
const path = require('node:path')

const mode = process.env.EXPO_PUBLIC_ERROR_REPORTER ?? 'bolide'
const out = path.join(__dirname, '..', 'src', 'logger', 'reporting', 'reporter.gen.ts')

const templates = {
  bolide: `/* GENERATED by scripts/gen-error-reporter.js - mode: bolide. Do not edit. */
import * as bolide from '@bluesky/bolide'
import {getEntries} from '../logDump'

export async function identifyDevice(
  existingDeviceId: string | undefined,
  deviceId: Promise<string>,
): Promise<void> {
  try {
    bolide.setUser({id: existingDeviceId ?? (await deviceId)})
  } catch {
    // Device ID initialization is handled by app startup; telemetry is optional.
  }
}

export function recordFeatureFlagEvaluation(name: string, value: unknown) {
  if (typeof value !== 'boolean') return
  bolide.recordFlag(name, value)
}

export function sendErrorReport({
  title,
  description,
  handle,
}: {
  title: string
  description: string
  handle: string
}) {
  bolide.captureUserReport({
    title,
    description,
    handle,
    attachment: {
      filename: title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 32) + '.json',
      data: JSON.stringify(getEntries()),
    },
  })
}
`,
  none: `/* GENERATED by scripts/gen-error-reporter.js - mode: none. Do not edit. */
export async function identifyDevice(
  _existingDeviceId: string | undefined,
  _deviceId: Promise<string>,
): Promise<void> {}

export function recordFeatureFlagEvaluation(_name: string, _value: unknown) {}

export function sendErrorReport(_report: {
  title: string
  description: string
  handle: string
}) {}
`,
}

if (!(mode in templates)) {
  console.error(`unknown EXPO_PUBLIC_ERROR_REPORTER: ${mode}`)
  process.exit(1)
}

fs.mkdirSync(path.dirname(out), {recursive: true})
fs.writeFileSync(out, templates[mode])
console.log(`wrote ${out} (mode: ${mode})`)

// Boot selector: which setup module runs at app start. Same gen-file
// pattern so the unselected setup module is never referenced at all.
const bootOut = path.join(__dirname, '..', 'src', 'logger', 'reporting', 'reporter-boot.gen.ts')
const bootTemplates = {
  sentry: "/* GENERATED - mode: sentry */\nimport '../sentry/setup'\n",
  bolide: "/* GENERATED - mode: bolide */\nimport '../bolide'\n",
  none: '/* GENERATED - mode: none */\n',
}
fs.writeFileSync(bootOut, bootTemplates[mode])
console.log(`wrote ${bootOut} (mode: ${mode})`)
